"""Persistent alerts API. Alerts are generated by real system events (scans, storage breaches)."""
from typing import List

from fastapi import APIRouter, Depends, HTTPException, Query
from models import AlertOut, AlertUpdate
from database import alert_collection
from dependencies import get_current_user, serialize_doc, to_object_id

router = APIRouter()


@router.get("/", response_model=List[dict])
async def list_alerts(
    unread_only: bool = Query(False),
    limit: int = Query(50, ge=1, le=200),
    user: dict = Depends(get_current_user),
):
    """Alerts addressed to the current user (or broadcast to their role)."""
    query = {"$or": [{"recipient_id": str(user["_id"])}, {"recipient_id": None, "recipient_role": user["role"]}]}
    if unread_only:
        query["is_read"] = False
    alerts = []
    cursor = alert_collection.find(query).sort("created_at", -1).limit(limit)
    async for document in cursor:
        alerts.append(serialize_doc(document))
    return alerts


@router.get("/unread-count")
async def unread_count(user: dict = Depends(get_current_user)):
    query = {"$or": [{"recipient_id": str(user["_id"])}, {"recipient_id": None, "recipient_role": user["role"]}]}
    count = await alert_collection.count_documents({**query, "is_read": False})
    return {"unread": count}


@router.patch("/{alert_id}", response_model=AlertOut)
async def mark_alert(alert_id: str, update: AlertUpdate, user: dict = Depends(get_current_user)):
    doc = await alert_collection.find_one({"_id": to_object_id(alert_id)})
    if not doc:
        raise HTTPException(status_code=404, detail="Alert not found")
    # Personal alerts: recipient only. Broadcasts (recipient_id None): any user
    # of the targeted role may mark their copy read.
    if doc.get("recipient_id") is None:
        if doc.get("recipient_role") != user["role"]:
            raise HTTPException(status_code=403, detail="Not your alert")
    elif doc.get("recipient_id") != str(user["_id"]):
        raise HTTPException(status_code=403, detail="Not your alert")
    await alert_collection.update_one({"_id": doc["_id"]}, {"$set": {"is_read": update.is_read}})
    updated = await alert_collection.find_one({"_id": doc["_id"]})
    return serialize_doc(updated)
